{
  "units": [
    {
      "quote_ref": "F000:F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Provides the section title '8 FAM 801.2-1 Introduction' and amendment metadata '(CT:CITZ-132; 08-07-2025)' without substantive operational rules."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "The stated purpose of subchapter 8 FAM 801.2 is to provide guidance regarding the use of information request letters (IRLs) and information notices (INs)."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "IRLs are defined as personalized, standardized letters containing a date and signature block that request additional information, documentation, or action needed from the applicant to process a passport application."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Adjudicators must fully adjudicate the passport application prior to suspending it to ensure that all issues are addressed."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "IRLs have been carefully crafted to communicate statutory, regulatory, and other Department requirements clearly and accurately."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F003"],
      "kind": "prohibition",
      "meaning": "Passport agencies and centers are prohibited from making unilateral changes or alterations to IRLs without the approval of the Office of Adjudication (CA/PPT/S/A), unless an exception applies."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F003"],
      "kind": "exception",
      "meaning": "Passport agencies and centers may alter or change IRLs on a case-by-case basis with the approval of passport agency or center management in extenuating circumstances (such as when an applicant is requested to submit a birth certificate instead of a notification of birth registration, but insists that the notification is the birth certificate)."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F003"],
      "kind": "requirement",
      "meaning": "Posts are required to use the cleared language in IRLs."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F003"],
      "kind": "permission",
      "meaning": "Posts are authorized to modify the cleared IRL language to suit local logistical requirements and other local concerns, such as available documentation."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "IRLs do not constitute adjudicative guidance."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "A passport application must first be adjudicated in accordance with 8 FAM, and only then must the appropriate IRL be selected to address any deficiencies with the passport or Consular Report of Birth Abroad (CRBA)."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "INs are standardized notices that provide passport bearers with information about their passports (such as explaining why a passport was limited in validity and/or what documentation is needed to obtain a fully valid passport), and are crafted to communicate this information clearly and accurately."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "Passport agencies and centers are prohibited from making unilateral changes or alterations to INs without the approval of CA/PPT/S/A, unless an exception applies."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "exception",
      "meaning": "Passport agencies and centers may make changes or alterations to INs in extenuating circumstances on a case-by-case basis with the approval of passport agency or center management (for example, when using endorsement 46 to limit a passport for a special problem)."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "INs do not require any response from the applicant and do not need to be personalized with the applicant's name and address."
    },
    {
      "quote_ref": "F008",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "When tailoring correspondence to a situation, posts are permitted either to consult Passport Services' IRL index and IN index or to contact AskPPTAdjudication@state.gov."
    }
  ]
}
